import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, CheckCircle2, FileUp, ShieldCheck } from 'lucide-react';
import { saveExternalClientIntakeSection, submitExternalClientIntake, uploadExternalClientIntakeDocument } from '../../lib/fiteatsyConsultantsApi';

const sections=[
  ['aboutYou','About You'],['medicalHistory','Medical History'],['conditionsSymptoms','Conditions & Symptoms'],
  ['allergiesFamilyHistory','Allergies & Family History'],['medicationsSupplements','Medications & Supplements'],
  ['lifestyle','Lifestyle'],['sleepStress','Sleep & Stress'],['activityHydration','Activity & Hydration'],
  ['nutrition','Nutrition & Food Preferences'],['goals','Goals'],['measurements','Measurements'],
  ['womensHealth',"Women's Health"],['reportsDocuments','Reports & Documents'],['review','Review'],['consent','Consent & Submit']
];
const inputs={
  aboutYou:[['firstName','First name','text',true],['lastName','Last name','text',true],['dateOfBirth','Date of birth','date',true],['gender','Gender','select'],['mobile','Mobile','tel'],['email','Email','email'],['occupation','Occupation','text'],['location','Location','text']],
  medicalHistory:[['diagnoses','Existing diagnoses or conditions','textarea'],['majorIllnesses','Previous major illnesses','textarea'],['surgeries','Surgeries or procedures','textarea'],['hospitalisations','Hospitalisations','textarea'],['currentCare','Current medical care','textarea']],
  conditionsSymptoms:[['conditions','Known conditions (comma separated)','textarea'],['symptoms','Current symptoms','textarea'],['other','Other details','textarea']],
  allergiesFamilyHistory:[['foodAllergies','Food allergies and reactions','textarea'],['medicationAllergies','Medication allergies and reactions','textarea'],['environmentalAllergies','Environmental allergies','textarea'],['familyHistory','Family history','textarea'],['notes','Other notes','textarea']],
  lifestyle:[['activityPattern','Occupation and activity pattern','textarea'],['workSchedule','Work schedule','text'],['workSetting','Work setting','select'],['smoking','Smoking','select'],['alcohol','Alcohol use','text'],['caffeine','Caffeine intake','text'],['dailyRoutine','Typical daily routine','textarea']],
  sleepStress:[['bedtime','Usual bedtime','time'],['wakeTime','Usual wake time','time'],['sleepHours','Average sleep duration (hours)','number'],['sleepQuality','Sleep quality','select'],['sleepConcerns','Sleep concerns','textarea'],['stressRating','Self-rated stress (0–10)','number'],['stressors','Major stressors','textarea'],['relaxation','Relaxation practices','textarea']],
  activityHydration:[['activityLevel','Activity level','select'],['exerciseFrequency','Exercise frequency','text'],['exerciseType','Exercise type','text'],['exerciseMinutes','Approximate duration (minutes)','number'],['sedentaryHours','Sedentary time (hours/day)','number'],['waterLitres','Water intake (litres/day)','number'],['beverages','Common beverages','textarea']],
  nutrition:[['dietPreference','Diet preference','select'],['foodAllergies','Food allergies','textarea'],['intolerances','Food intolerances','textarea'],['dislikedFoods','Disliked foods','textarea'],['foodsAvoided','Foods avoided','textarea'],['restrictions','Religious or cultural restrictions','textarea'],['mealTiming','Meal timing','text'],['mealsPerDay','Meals per day','number'],['eatingOut','Eating-out frequency','text'],['cravings','Cravings','textarea'],['snacking','Snacking pattern','textarea'],['breakfast','Typical breakfast','textarea'],['lunch','Typical lunch','textarea'],['dinner','Typical dinner','textarea'],['snacks','Common snacks','textarea']],
  goals:[['primaryGoal','Primary goal','select'],['secondaryGoals','Secondary goals','textarea'],['goalNotes','Goal notes','textarea']],
  measurements:[['height','Height','number'],['heightUnit','Height unit','select'],['weight','Weight','number'],['weightUnit','Weight unit','select'],['waist','Waist circumference (cm)','number'],['hip','Hip circumference (cm)','number'],['bloodPressure','Blood pressure','text'],['restingHeartRate','Resting heart rate (bpm)','number'],['bloodGlucose','Self-known blood glucose','text'],['other','Other measurements','textarea'],['recordedAt','Recorded at','date']],
  womensHealth:[['answerPreference','Response preference','select'],['menstrualStatus','Menstrual status','text'],['cycleRegularity','Cycle regularity','text'],['cycleLength','Average cycle length (days)','number'],['lastPeriod','Last menstrual period','date'],['pcosHistory','PCOS history','select'],['pregnancyStatus','Pregnancy status','select'],['breastfeeding','Breastfeeding','select'],['menopause','Menopause/perimenopause','select'],['notes','Reproductive-health notes','textarea']]
};
const options={gender:['FEMALE','MALE','NON_BINARY','PREFER_NOT_TO_SAY','OTHER'],workSetting:['HOME','OFFICE','MIXED','OTHER'],smoking:['NEVER','FORMER','CURRENT','PREFER_NOT_TO_SAY'],sleepQuality:['POOR','FAIR','GOOD','VERY_GOOD'],activityLevel:['SEDENTARY','LIGHT','MODERATE','ACTIVE','VERY_ACTIVE'],dietPreference:['VEGETARIAN','EGGITARIAN','NON_VEGETARIAN','VEGAN','OTHER'],primaryGoal:['WEIGHT_LOSS','WEIGHT_GAIN','MUSCLE_GAIN','DIABETES_SUPPORT','PCOS_SUPPORT','THYROID_SUPPORT','CHOLESTEROL_MANAGEMENT','DIGESTIVE_HEALTH','ENERGY','RECOVERY','GENERAL_WELLNESS','OTHER'],heightUnit:['cm','ft/in'],weightUnit:['kg','lb'],answerPreference:['ANSWER','PREFER_NOT_TO_ANSWER'],pcosHistory:['YES','NO','UNKNOWN','PREFER_NOT_TO_ANSWER'],pregnancyStatus:['YES','NO','PREFER_NOT_TO_ANSWER'],breastfeeding:['YES','NO','PREFER_NOT_TO_ANSWER'],menopause:['NO','PERIMENOPAUSE','MENOPAUSE','PREFER_NOT_TO_ANSWER']};
const blankRow={name:'',dose:'',frequency:'',reason:'',startDate:''};

export default function ExternalClientHealthIntake({token,initial,practiceName,onComplete}){
  const initialSections=initial.sections||{};const [answers,setAnswers]=useState(initialSections);const applicable=useMemo(()=>sections.filter(([key])=>key!=='womensHealth'||answers.aboutYou?.gender==='FEMALE'),[answers.aboutYou?.gender]);
  const initialIndex=Math.max(0,applicable.findIndex(([key])=>key===initial.currentSection));const [index,setIndex]=useState(initialIndex<0?0:initialIndex);const [completion,setCompletion]=useState(initial.completionPercent||0);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [consent,setConsent]=useState(false);const [documents,setDocuments]=useState(initial.documents||[]);
  const [key,title]=applicable[index];const data=answers[key]||{};
  const set=(field,value)=>setAnswers(v=>({...v,[key]:{...(v[key]||{}),[field]:value}}));
  const initialRender=useRef(true);useEffect(()=>{if(initialRender.current){initialRender.current=false;return;}if(['review','consent','reportsDocuments'].includes(key)||!Object.keys(data).length)return;if(key==='aboutYou'&&(!data.firstName||!data.lastName||!data.dateOfBirth))return;const timer=setTimeout(()=>saveExternalClientIntakeSection(token,key,data,key).then(result=>setCompletion(result.intake.completionPercent)).catch(()=>{}),900);return()=>clearTimeout(timer);},[token,key,data]);
  const save=async(nextIndex=index+1)=>{if(key==='review'||key==='consent'){setIndex(Math.min(nextIndex,applicable.length-1));return;}if(key==='aboutYou'&&(!data.firstName||!data.lastName||!data.dateOfBirth)){setError('First name, last name, and date of birth are required.');return;}setSaving(true);setError('');try{const nextKey=applicable[Math.min(nextIndex,applicable.length-1)][0];const result=await saveExternalClientIntakeSection(token,key,data,nextKey);setCompletion(result.intake.completionPercent);setIndex(Math.min(nextIndex,applicable.length-1));}catch(e){setError(e.message||'Unable to save this section.');}finally{setSaving(false);}};
  const upload=async(e)=>{const file=e.target.files?.[0];if(!file)return;setSaving(true);setError('');try{const r=await uploadExternalClientIntakeDocument(token,data.category||'OTHER_HEALTH_DOCUMENT',file);setDocuments(v=>[...v,r.document]);set('uploaded',true);}catch(err){setError(err.message||'Unable to upload document.');}finally{setSaving(false);e.target.value='';}};
  const submit=async()=>{if(!consent){setError('Please provide consent before submitting.');return;}setSaving(true);setError('');try{const result=await submitExternalClientIntake(token);onComplete(result.practiceName||practiceName);}catch(e){setError(e.message||'Unable to submit your health profile.');}finally{setSaving(false);}};
  return <div className="min-h-screen bg-[#f6f7f8] px-4 py-6 sm:px-6 sm:py-10"><div className="mx-auto max-w-4xl"><header className="mb-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-xl bg-slate-950 text-white"><ShieldCheck size={21}/></div><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-slate-500">Secure health profile</p><h1 className="text-lg font-semibold">{practiceName}</h1></div></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full bg-emerald-600 transition-all" style={{width:`${completion}%`}}/></div><div className="mt-2 flex justify-between text-xs text-slate-500"><span>Step {index+1} of {applicable.length}</span><span>{completion}% saved</span></div></header><main className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-8"><p className="text-sm font-medium text-emerald-700">{title}</p><h2 className="mt-1 text-2xl font-semibold">{key==='review'?'Review your health profile':key==='consent'?'Consent and submit':title}</h2><div className="mt-6">{key==='medicationsSupplements'?<MedicationSection value={data} onChange={(field,value)=>set(field,value)}/>:key==='reportsDocuments'?<DocumentSection value={data} set={set} documents={documents} upload={upload}/>:key==='review'?<Review answers={answers} sections={applicable} onEdit={section=>setIndex(applicable.findIndex(([k])=>k===section))}/>:key==='consent'?<Consent checked={consent} onChange={setConsent}/>:<Fields fields={inputs[key]||[]} value={data} set={set}/>}</div>{error&&<p role="alert" className="mt-5 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</p>}<div className="mt-8 flex items-center justify-between border-t border-slate-100 pt-5"><button disabled={index===0||saving} onClick={()=>setIndex(v=>Math.max(0,v-1))} className="inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-slate-600 disabled:opacity-30"><ArrowLeft size={17}/>Back</button>{key==='consent'?<button disabled={saving} onClick={submit} className="rounded-xl bg-emerald-700 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{saving?'Submitting…':'Submit health profile'}</button>:<button disabled={saving} onClick={()=>save()} className="inline-flex items-center gap-2 rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{saving?'Saving…':'Save & Continue'}<ArrowRight size={17}/></button>}</div></main><p className="mt-5 text-center text-xs text-slate-500">Your information is securely shared only with {practiceName}.</p></div></div>;
}
function Fields({fields,value,set}){return <div className="grid gap-5 sm:grid-cols-2">{fields.map(([key,label,type,required])=><label key={key} className={`space-y-1.5 text-sm font-medium text-slate-700 ${type==='textarea'?'sm:col-span-2':''}`}><span>{label}{required?' *':''}</span>{type==='textarea'?<textarea rows={3} value={value[key]||''} onChange={e=>set(key,e.target.value)} className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 outline-none focus:border-slate-900"/>:type==='select'?<select value={value[key]||''} onChange={e=>set(key,e.target.value)} className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5"><option value="">Select</option>{(options[key]||['YES','NO','NOT_APPLICABLE']).map(v=><option key={v}>{v}</option>)}</select>:<input required={required} type={type} min={type==='number'?'0':undefined} value={value[key]||''} onChange={e=>set(key,e.target.value)} className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 outline-none focus:border-slate-900"/>}</label>)}</div>}
function MedicationSection({value,onChange}){const rows=(kind)=>value[kind]||[blankRow];const update=(kind,i,field,v)=>onChange(kind,rows(kind).map((r,n)=>n===i?{...r,[field]:v}:r));const add=kind=>onChange(kind,[...rows(kind),blankRow]);return <div className="space-y-7">{[['medications','Medication'],['supplements','Supplement']].map(([kind,label])=><section key={kind}><div className="flex justify-between"><h3 className="font-semibold">{label}s</h3><button onClick={()=>add(kind)} className="text-sm font-semibold text-emerald-700">+ Add {label.toLowerCase()}</button></div><div className="mt-3 space-y-3">{rows(kind).map((row,i)=><div key={i} className="grid gap-3 rounded-xl bg-slate-50 p-4 sm:grid-cols-2"><input aria-label={`${label} name`} placeholder="Name" value={row.name} onChange={e=>update(kind,i,'name',e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input placeholder="Dose" value={row.dose} onChange={e=>update(kind,i,'dose',e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input placeholder="Frequency" value={row.frequency} onChange={e=>update(kind,i,'frequency',e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input placeholder="Reason (optional)" value={row.reason} onChange={e=>update(kind,i,'reason',e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/></div>)}</div></section>)}</div>}
function DocumentSection({value,set,documents,upload}){return <div><label className="text-sm font-medium text-slate-700">Document category<select value={value.category||'LAB_REPORT'} onChange={e=>set('category',e.target.value)} className="mt-2 block w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5"><option>LAB_REPORT</option><option>PRESCRIPTION</option><option>MEDICAL_REPORT</option><option>OTHER_HEALTH_DOCUMENT</option></select></label><label className="mt-5 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 p-6 text-sm font-semibold text-slate-700"><FileUp size={19}/>Upload PDF, JPEG, or PNG<input type="file" accept="application/pdf,image/jpeg,image/png" onChange={upload} className="sr-only"/></label><div className="mt-4 space-y-2">{documents.map(d=><div key={d.id} className="flex items-center gap-2 rounded-lg bg-slate-50 px-3 py-2 text-sm"><CheckCircle2 size={16} className="text-emerald-600"/>{d.fileName}</div>)}</div><p className="mt-3 text-xs text-slate-500">Maximum 12MB. Biomarker extraction is not performed during intake.</p></div>}
function Review({answers,sections,onEdit}){return <div className="space-y-3">{sections.filter(([k])=>!['review','consent'].includes(k)).map(([key,title])=>{const entries=Object.entries(answers[key]||{});return <section key={key} className="rounded-xl border border-slate-200 p-4"><div className="flex justify-between"><h3 className="font-semibold">{title}</h3><button onClick={()=>onEdit(key)} className="text-sm font-semibold text-emerald-700">Edit</button></div>{entries.length?<dl className="mt-3 grid gap-2 text-sm sm:grid-cols-2">{entries.map(([label,value])=><div key={label}><dt className="text-slate-500">{label.replace(/([A-Z])/g,' $1')}</dt><dd className="break-words font-medium text-slate-800">{Array.isArray(value)?`${value.length} item${value.length===1?'':'s'}`:String(value||'Not provided')}</dd></div>)}</dl>:<p className="mt-2 text-sm text-slate-600">No information provided</p>}</section>})}</div>}
function Consent({checked,onChange}){return <div className="rounded-xl bg-slate-50 p-5"><label className="flex items-start gap-3"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)} className="mt-1 h-4 w-4"/><span className="text-sm leading-6 text-slate-700">I consent to provide health information to this Consultant/practice and to the secure storage and processing of my submitted health information and uploaded documents for consultation and care purposes. This does not include marketing consent.</span></label></div>}
